 for(unsigned i=0;i<2;i++){free(g_diff_paths[i]);g_diff_paths[i]=wdup(i?native:local);}g_diff_request.session++;g_diff_request.wsl=1;g_diff_request.reserved=0;sidepanel_show(g.hwnd,diff_app(),SIDEPANEL_KEEP,0);diff_send_pair();pump_content(250);
 uint64_t sessions[]={g_content_request.session,g_space_request.session,g_duplicate_request.session,g_diff_request.session,g_git_request.session};uint32_t generation=g_content_generation;
 sidepanel_close();pump_content(20);int live=sidepanel_running(content_app())+sidepanel_running(space_app())+sidepanel_running(duplicate_app())+sidepanel_running(diff_app())+sidepanel_running(git_app());CHECK("captured native scopes span the four-slot panel cache",live==4&&g_content_root&&g_space_root&&g_duplicate_request.count&&g_diff_paths[0]&&g_git_folder);
 settings_apply(off,strlen(off));pump_content(100);
 CHECK("WSL-only real settings reload retires all five affected helpers",!sidepanel_running(content_app())&&!sidepanel_running(space_app())&&!sidepanel_running(duplicate_app())&&!sidepanel_running(diff_app())&&!sidepanel_running(git_app()));
 CHECK("revocation changes every native request session",g_content_request.session!=sessions[0]&&g_space_request.session!=sessions[1]&&g_duplicate_request.session!=sessions[2]&&g_diff_request.session!=sessions[3]&&g_git_request.session!=sessions[4]);
 CHECK("native roots and mixed ordinary-Diff pair cannot be replayed",!g_content_root&&!g_space_root&&!g_duplicate_request.count&&!g_diff_paths[0]&&!g_diff_paths[1]&&!g_diff_request.wsl&&!g_git_request.wsl);
 const wchar_t *apps[]={content_app(),space_app(),duplicate_app(),diff_app(),git_app()};panelp_input refresh={.msg=WM_KEYDOWN,.wparam=VK_F5};int refused=1;for(unsigned i=0;i<5;i++)refused&=!sidepanel_send(apps[i],PANELP_INPUT,&refresh,sizeof refresh)&&!sidepanel_generation(apps[i]);CHECK("Start/Refresh cannot reach the retired native helper intake",refused);
 uint64_t ticket=g.panes[1].nav_ticket;send_result(sessions[0],generation,L"notes.md");CHECK("old native result authority is invalid after policy reload",g.panes[1].nav_ticket==ticket);
 settings_apply(on,strlen(on));content_open_root(left);space_open_root(left);duplicate_open_roots((const wchar_t *const[]){left,right},2);git_open_folder(left);free(g_diff_paths[0]);free(g_diff_paths[1]);g_diff_paths[0]=wdup(local);g_diff_paths[1]=join(right,L"other.txt");g_diff_request.session++;g_diff_request.wsl=0;sidepanel_show(g.hwnd,diff_app(),SIDEPANEL_KEEP,0);diff_send_pair();pump_content(250);
 uint32_t launches[5];for(unsigned i=0;i<5;i++)launches[i]=sidepanel_generation(apps[i]);settings_apply(off,strlen(off));pump_content(30);int kept=1,retained=0;for(unsigned i=0;i<5;i++)if(launches[i]){retained++;kept&=launches[i]==sidepanel_generation(apps[i]);}CHECK("Windows-only retained sessions survive disabled WSL policy",kept&&retained==4);CHECK("all retained Windows requests capture disabled WSL policy",!g_content_request.wsl&&!g_space_request.wsl&&!g_duplicate_request.wsl&&!g_diff_request.wsl&&!g_git_request.wsl);
 sidepanel_show(g.hwnd,content_app(),SIDEPANEL_KEEP,0);pump_content(100);const wchar_t *query=L"previous";for(unsigned i=0;query[i];i++)panel_input(WM_CHAR,query[i],0,0);generation=g_content_generation;panel_input(WM_KEYDOWN,VK_RETURN,0,0);CHECK("Windows-only search still completes after native revocation",wait_search(generation));
 settings_apply(on,strlen(on));content_open_root(root);pump_content(150);generation=g_content_generation;query=L"needle";for(unsigned i=0;query[i];i++)panel_input(WM_CHAR,query[i],0,0);panel_input(WM_KEYDOWN,VK_RETURN,0,0);CHECK("fresh native request works after real policy re-enable",wait_search(generation)&&g_content_request.wsl);
