static void test_content_host_disabled_feature_and_shutdown(void){const char *settings="[functions]\nfile.find_content = off\nsvc.shell = off\nsvc.icons = off\n[panel.side]\nslide = off\n";fn_settings(settings,strlen(settings));fn_configure_all();pump_content(50);CHECK("disabled content feature retires only its owned helper",!fn_active(fn_find("file.find_content"))&&!sidepanel_running(content_app()));char report[65536];fn_report_csv(report,sizeof report);CHECK("content and preview registry lifetimes remain valid",strstr(report,"metric,fn_violations,,,,0,")!=NULL);}
int wmain(int argc,wchar_t **argv){if(argc!=3)return 2;wcsncpy(left,argv[1],32767);wcsncpy(right,argv[2],32767);CoInitializeEx(NULL,COINIT_APARTMENTTHREADED);SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);fn_host host={host_now,host_arm,host_status};fn_init(&host);fn_register(app_functions,sizeof app_functions/sizeof *app_functions);functions_register();relay_register();palette_register();const char *settings="[functions]\nsvc.shell = off\nsvc.icons = off\n[panel.side]\nslide = off\n";fn_settings(settings,strlen(settings));fn_configure_all();g.engine=fpe_engine_create(NULL);g.dual=1;g.ratio=0.5;session_defaults(&g_ses);for(int i=0;i<2;i++){Pane *p=&g.panes[i];p->idx=i;p->ntabs=1;p->drop_row=-1;p->opts.dirs_first=1;}HINSTANCE instance=GetModuleHandleW(NULL);register_class(L"OpenPilot",main_proc,0,instance);register_class(L"OpenPilotPane",pane_proc,CS_DBLCLKS,instance);register_class(L"OpenPilotTree",tree_proc,CS_DBLCLKS,instance);register_class(L"OpenPilotDebug",dbg_proc,0,instance);HWND window=CreateWindowExW(0,L"OpenPilot",L"Owned content integration",WS_OVERLAPPEDWINDOW|WS_CLIPCHILDREN,80,80,1300,850,NULL,NULL,instance,NULL);if(!window)return 3;for(int i=0;i<2;i++){fpe_dir *dir=read_start(i?right:left);if(dir){p_show_dir(&g.panes[i],dir,NULL,0);fpe_dir_release(dir);}}ShowWindow(window,SW_SHOWNOACTIVATE);UpdateWindow(window);pump_content(20);test_content_host_real_search_opens_exact_preview_match();test_content_host_stale_authority_and_changed_source();test_content_host_native_wsl_match_navigation();test_content_host_optional_wsl_reload_revokes_captured_sessions();test_content_host_disabled_feature_and_shutdown();DestroyWindow(window);pump_content(100);settings_save_join();folderwatch_join();fpe_engine_destroy(g.engine);CoUninitialize();printf("%d passed, %d failed; 5 content host selectors\n",passed,failed);return failed?1:0;}
